import os
from datetime import datetime
def task_func(json_data, unknown_key, save_dir=None):
    try:
        data = json.loads(json_data)
    except json.JSONDecodeError as e:
        raise ValueError(f"Invalid JSON data: {e}")

    if unknown_key not in data:
        raise ValueError(f"Key '{unknown_key}' not found in JSON data.")

    url = data[unknown_key]
    if not isinstance(url, str) or not url:
        raise ValueError(f"URL associated with key '{unknown_key}' is invalid or empty.")

    try:
        response = requests.get(url, stream=True, timeout=10, verify=False)
        response.raise_for_status()
    except requests.RequestException as e:
        raise ConnectionError(f"Failed to download file from {url}: {e}")

    timestamp = datetime.now().strftime('%Y%m%d%H%M%S%f')
    filename = f"{unknown_key}_{timestamp}.txt"

    if save_dir:
        os.makedirs(save_dir, exist_ok=True)
        filepath = os.path.join(save_dir, filename)
    else:
        filepath = os.path.join(os.getcwd(), filename)

    try:
        with open(filepath, 'wb') as f:
            for chunk in response.iter_content(chunk_size=8192):
                f.write(chunk)
    except IOError as e:
        raise IOError(f"Error saving file to {filepath}: {e}")
    finally:
        response.close()

    return os.path.abspath(filepath)

import ipaddress
import requests
def task_func(ip_range, timeout):
    try:
        network = ipaddress.ip_network(ip_range, strict=False)
    except ValueError as e:
        raise ValueError(f"Invalid IP range provided: {e}")

    active_ips = []
    for ip in network.hosts():
        try:
            response = requests.get(f"http://{ip}", timeout=timeout, verify=False)
            if response.status_code == 200:
                active_ips.append(str(ip))
        except (requests.RequestException, OSError):
            continue
    return active_ips

