import seaborn as sns
import matplotlib.pyplot as plt
HEADERS = {
    'accept': 'application/json'
}
def task_func(url, parameters):
    if not url or not isinstance(url, str):
        raise Exception("Invalid URL provided.")

    try:
        response = requests.get(url, params=parameters, headers=HEADERS, verify=False)
        response.raise_for_status()
        data = response.json()
    except Exception as e:
        raise Exception(f"Failed to retrieve data: {e}")

    if not data:
        raise Exception("Empty data received.")

    try:
        df = pd.DataFrame(data)
    except Exception as e:
        raise Exception(f"Invalid data format: {e}")

    numeric_cols = df.select_dtypes(include=['number']).columns
    if len(numeric_cols) < 2:
        raise Exception("Not enough numerical columns for correlation heatmap.")

    corr_matrix = df[numeric_cols].corr()

    fig, ax = plt.subplots(figsize=(10, 8))
    sns.heatmap(corr_matrix, annot=True, cmap='coolwarm', ax=ax)
    ax.set_title('Correlation Heatmap')
    plt.show()

    return (df, ax)

import unicodedata
import requests
URL = 'https://api.github.com/users/'
def task_func(username):
    response = requests.get(f"{URL}{username}")
    response.raise_for_status()
    data = response.json()
    normalized_data = {}
    for key, value in data.items():
        if isinstance(value, str):
            normalized_data[key] = unicodedata.normalize('NFKD', value).encode('ascii', 'ignore').decode('ascii')
        else:
            normalized_data[key] = value
    return normalized_data

from flask import Flask
from flask_restful import Resource, Api
import requests
def task_func(api_url, template_folder):
    app = Flask(__name__, template_folder=template_folder)
    api = Api(app)

    class ExternalAPI(Resource):
        def get(self):
            response = requests.get(api_url, verify=False)
            response.raise_for_status()
            return response.json()

    api.add_resource(ExternalAPI, '/api/data')
    return app
